"""Sound for MTG's videos, all generated by code (no recordings, no licences, no copyright claims).

1. Sound effects into public/sfx/ (shared by every video): uses the GrowKaz Stickman Studio plugin's procedural
   effects when the plugin is installed, plus a few of our own (coin, stamp, shutter, paper).
2. A music bed for one video from a mood plan: uses the plugin's procedural score (moods cross-fade at story turns).

Usage:
  python3 scripts/make_sound.py sfx   [--kit <path to growkaz kit>]
  python3 scripts/make_sound.py music public/videos/01/music-plan.json public/videos/01/music-bed.wav [--kit ...]
music-plan.json: {"total": 263.2, "seed": 7, "plan": [{"start": 0, "end": 13.5, "mood": "mystery", "intensity": 0.45}, ...]}
Moods: mystery, tension, action, wonder, hopeful, sad, triumph, playful, calm, dark, epic.
"""
import argparse
import glob
import json
import os
import sys
import wave

import numpy as np

SR = 48000
HERE = os.path.dirname(os.path.abspath(__file__))
SFX_DIR = os.path.join(HERE, '..', 'public', 'sfx')
KIT_GUESS = glob.glob('/root/.claude/**/make-2d-video/kit/audio', recursive=True)


def load_kit(path):
    audio = path or (KIT_GUESS[0] if KIT_GUESS else None)
    if not audio or not os.path.isdir(audio):
        sys.exit('GrowKaz kit not found: install the growkaz-stickman plugin or pass --kit <kit>/audio')
    if os.path.basename(audio) != 'audio':
        audio = os.path.join(audio, 'audio')
    sys.path.insert(0, audio)
    return audio


def write(path, x):
    x = np.asarray(x, dtype=np.float32)
    if x.ndim == 1:
        x = np.stack([x, x], axis=1)
    peak = np.max(np.abs(x)) or 1.0
    x = x / peak * 0.89  # about -1 dBFS
    with wave.open(path, 'wb') as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(SR)
        w.writeframes((np.clip(x, -1, 1) * 32767).astype('<i2').tobytes())


def t(sec):
    return np.arange(int(sec * SR)) / SR


def bandnoise(sec, lo, hi, seed):
    rng = np.random.default_rng(seed)
    n = rng.standard_normal(int(sec * SR))
    spec = np.fft.rfft(n)
    f = np.fft.rfftfreq(len(n), 1 / SR)
    spec[(f < lo) | (f > hi)] = 0
    return np.fft.irfft(spec, len(n))


# Our own effects
def coin():
    out = np.zeros(int(0.9 * SR))
    for k, (start, base) in enumerate([(0.0, 2100), (0.12, 2350)]):
        tt = t(0.75)
        partials = sum(np.sin(2 * np.pi * base * r * tt) * a for r, a in [(1, 1), (2.76, 0.6), (5.4, 0.35), (8.9, 0.2)])
        s = partials * np.exp(-tt * 9) * (1 - np.exp(-tt * 400))
        i = int(start * SR)
        out[i:i + len(s)] += s[:len(out) - i] * (1 if k == 0 else 0.7)
    return out


def stamp():
    tt = t(0.6)
    thud = np.sin(2 * np.pi * (70 + 40 * np.exp(-tt * 30)) * tt) * np.exp(-tt * 11)
    slap = bandnoise(0.6, 200, 3500, 3) * np.exp(-tt * 45) * 0.6
    return thud + slap


def shutter():
    dur = 1.0
    tt = t(dur)
    clicks = np.zeros_like(tt)
    rng = np.random.default_rng(5)
    for c in np.arange(0, 0.85, 1 / 28):
        i = int(c * SR)
        n = int(0.012 * SR)
        clicks[i:i + n] += bandnoise(0.012, 800, 6000, int(c * 1000))[:n] * (0.6 + 0.4 * rng.random())
    roll = bandnoise(dur, 60, 400, 9) * 0.5
    env = np.minimum(1, tt / 0.05) * np.where(tt < 0.85, 1, np.exp(-(tt - 0.85) * 30))
    end = np.sin(2 * np.pi * 90 * tt) * np.exp(-np.maximum(0, tt - 0.85) * 20) * (tt > 0.85)
    return (clicks + roll) * env + end * 0.8


def paper():
    tt = t(0.55)
    n = bandnoise(0.55, 900, 7000, 11)
    flutter = 0.5 + 0.5 * np.abs(np.sin(2 * np.pi * 14 * tt))
    return n * flutter * np.sin(np.pi * tt / 0.55) ** 2


KIT_SFX = ['whoosh', 'swish', 'pop', 'blip', 'tick', 'counter', 'ding', 'shimmer', 'stinger', 'riser', 'impact', 'hit',
           'flash', 'glitch', 'powerup', 'heartbeat', 'clock']


def cmd_sfx(kit):
    load_kit(kit)
    import sfx  # noqa: E402  (the plugin's procedural library)
    os.makedirs(SFX_DIR, exist_ok=True)
    import subprocess
    made = [(n, sfx.make(n, seed=3)) for n in KIT_SFX] + [(n, fn()) for n, fn in [('coin', coin), ('stamp', stamp), ('shutter', shutter), ('paper', paper)]]
    for name, x in made:
        wav = os.path.join(SFX_DIR, f'{name}.wav')
        write(wav, x)
        subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', wav, '-c:a', 'libmp3lame', '-b:a', '160k', wav[:-4] + '.mp3'], check=True)
        os.remove(wav)
    print(f'{len(KIT_SFX) + 4} effects -> {os.path.normpath(SFX_DIR)}')


def cmd_music(kit, plan_path, out):
    load_kit(kit)
    import music  # noqa: E402
    p = json.load(open(plan_path, encoding='utf-8'))
    x = music.render_score(p['plan'], p['total'], seed=p.get('seed', 1))
    write(out, x)
    print(f'music bed {p["total"]:.1f} s -> {out}')


ap = argparse.ArgumentParser()
ap.add_argument('what', choices=['sfx', 'music'])
ap.add_argument('plan', nargs='?')
ap.add_argument('out', nargs='?')
ap.add_argument('--kit')
a = ap.parse_args()
if a.what == 'sfx':
    cmd_sfx(a.kit)
else:
    cmd_music(a.kit, a.plan, a.out)
